<template>
  <div class="activete">
    <d2-container>
      <el-form :model="form" :rules="rules" ref="form" class="custom-form" label-width="85px">
        <el-form-item label="机器编码" prop="uuid_code">
          <el-input v-model="form.uuid_code" />
        </el-form-item>
        <el-form-item label="用户名" prop="username">
          <el-input v-model="form.username" />
        </el-form-item>

        <el-form-item label="公司" prop="company">
          <el-input v-model="form.company" />
        </el-form-item>

        <el-form-item label="电话" prop="mobile">
          <el-input v-model="form.mobile" />
        </el-form-item>

        <el-form-item label="国家" prop="nation">
          <el-select v-model="form.nation" placeholder="请选择国家">
            <el-option label="中国" value="中国" />
          </el-select>
        </el-form-item>

        <el-form-item label="省" prop="province">
          <!-- <el-input v-model="form.province" /> -->
          <el-select v-model="form.province" @change="handleProvinceChange" placeholder="选择省份" filterable allow-create>
            <el-option v-for="province in provinceOptions" :key="province.value" :label="province.label" :value="province.value" />
          </el-select>
        </el-form-item>

        <el-form-item label="市" prop="city">
          <!-- <el-input v-model="form.city" /> -->
          <el-select v-model="form.city" placeholder="选择市" filterable allow-create>
            <el-option v-for="city in filteredCities" :key="city.value" :label="city.label" :value="city.value" />
          </el-select>
        </el-form-item>

        <el-form-item label="地址" prop="address">
          <el-input v-model="form.address" />
        </el-form-item>

        <el-form-item label="激活时间" prop="time">
          <el-date-picker v-model="form.time" type="datetime" format="yyyy-MM-dd HH:mm:ss" value-format="yyyy-MM-dd HH:mm:ss" placeholder="选择激活时间" />
        </el-form-item>
        <el-form-item label="有效时间" prop="valid_until">
          <el-date-picker v-model="form.valid_until" type="date" format="yyyy-MM-dd" value-format="yyyy-MM-dd" placeholder="选择有效时间" />
        </el-form-item>

        <el-form-item>
          <el-button type="primary" @click="submitForm">提交</el-button>
          <el-button @click="resetForm">重置</el-button>
        </el-form-item>
      </el-form>
    </d2-container>
  </div>
</template>

<script>
import axios from 'axios'
import { activate } from '@/api/activate/index';
import provinceOption from './json/index'
export default {
  data() {
    return {
      // form: {
      //   username: '高清灵',
      //   company: '清河科技',
      //   nation: '中国',
      //   mobile: '13835801245',
      //   province: '山西',
      //   city: '太原',
      //   address: '小店区宇翔大厦',
      //   time: ''
      // },
      provinceOptions: provinceOption,
      form: {
        uuid_code: '',
        username: '',
        company: '',
        nation: '中国',
        mobile: '',
        province: '',
        city: '',
        address: '',
        time: '',
        valid_until:''
      },
      rules: {
        uuid_code: [
          { required: true, message: '请输入机器编码', trigger: 'blur' }
        ],
        username: [
          { required: true, message: '请输入用户名', trigger: 'blur' }
        ],
        company: [
          { required: true, message: '请输入公司名称', trigger: 'blur' }
        ],
        nation: [
          { required: true, message: '请输入国家', trigger: 'blur' }
        ],
        mobile: [
          { required: true, message: '请输入电话', trigger: 'blur' },
          { pattern: /^[0-9]{10,15}$/, message: '请输入有效的电话号码', trigger: 'blur' }
        ],
        province: [
          { required: true, message: '请输入省份', trigger: 'blur' }
        ],
        city: [
          { required: true, message: '请输入城市', trigger: 'blur' }
        ],
        address: [
          { required: true, message: '请输入地址', trigger: 'blur' }
        ],
        time: [
          { required: true, message: '请输入激活时间', trigger: 'blur' }
        ],
        valid_until: [
          { required: true, message: '请输入有效时间', trigger: 'blur' }
        ]
      },
      timeInterval: null,
    }
  },
  computed: {
    filteredCities() {
      const selectedProvince = this.provinceOptions.find(city => city.value === this.form.province);
      return selectedProvince ? selectedProvince.children : [];
    }
  },
  created() {

  },
  mounted() {
    this.updateCurrentTime();
    this.timeInterval = setInterval(this.updateCurrentTime, 1000);
  },
  beforeDestroy() {
    clearInterval(this.timeInterval);
  },
  methods: {
    handleProvinceChange() {
      this.form.city = ''; // 清空市选择
    },
    updateCurrentTime() {
      const now = new Date();
      this.form.time = now.toISOString().slice(0, 19).replace('T', ' ');
    },
    // 提交信息
    submitForm() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          const formData = new FormData();
          // 将表单数据添加到 FormData 对象
          for (const key in this.form) {
            if (this.form.hasOwnProperty(key)) {
              formData.append(key, this.form[key]);
            }
          }
          axios({
            url: activate.activateDownLoad,
            method: 'post',
            data: formData,
            headers: {
              'Content-Type': 'multipart/form-data' // 设置请求头为 form-data
            }
          }).then(response => {
            if (response.data.code == 200) {
              this.downloadFile(response.data.file)
              this.$message(
                {
                  type: 'success',
                  message: response.data.msg,
                }
              )
            }
          }).catch(rek => {
            console.log(rek);
          })
        } else {
          console.log('表单验证失败');
          return false;
        }
      });
    },
    // 重置信息
    resetForm() {
      this.$refs.form.resetFields();
    },
    // 下载文件
    downloadFile(file) {
      const fileUrl = file // 文件下载链接

      axios({
        url: fileUrl,
        method: 'GET',
        responseType: 'blob' // 重要: 指定响应类型为 blob
      })
        .then(response => {
          // 创建一个下载链接
          const url = window.URL.createObjectURL(new Blob([response.data]));
          const link = document.createElement('a');
          link.href = url;
          link.setAttribute('download', 'activation_file.ak'); // 指定下载文件名
          document.body.appendChild(link);
          link.click();

          // 清理
          link.remove();
          window.URL.revokeObjectURL(url);
        })
        .catch(error => {
          console.error('Error occurred while downloading the file:', error);
        });
    }
  }
}
</script>

<style lang="scss" scoped>
  .activete{
    width: 100%;
    height: 100%;
  }
.custom-form {
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  background-color: #f9f9f9;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}
</style>